package ng.com.createsoftware.fn_customer_service.client;

import ng.com.createsoftware.fn_customer_service.dto.request.CreateClientRequest;
import ng.com.createsoftware.fn_customer_service.dto.response.CreateClientResponse;
import org.springframework.cloud.openfeign.FeignClient;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestParam;

import java.util.List;

@FeignClient(name="fineract", url="${fineract.base-url}")
public interface FineractCustomerClient {
    @PostMapping("/v1/clients")
    CreateClientResponse create(@RequestBody CreateClientRequest request);

    @GetMapping("/v1/clients")
    List<CreateClientResponse> list(@RequestParam String status);                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
}
